package net.minecraft.world.inventory;import net.minecraft.world.Container;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.ItemStack;public class ChestMenu extends AbstractContainerMenu{public final int rows;private final Container container;public int clicks;public ChestMenu(MenuType<?> t,int id,Inventory i,Container c,int rows){this.rows=rows;this.container=c;c.startOpen(i.player);for(int j=0;j<rows*9;j++)slots.add(new Slot(c,j,0,0));}public Container getContainer(){return container;}protected void resetQuickCraft(){}public boolean stillValid(Player p){return true;}public void clicked(int slot,int button,ClickType type,Player player){clicks++;}public ItemStack quickMoveStack(Player p,int slot){return ItemStack.EMPTY;}}
